/******************************************************************
Stellar Dark by Octavia N. (https://github.com/Lolabird/stellar-dark-theme-trilium)
Inspired by https://github.com/Engr-AllanG/trilium-theme-Neon_Dark
******************************************************************/
/*****FONT IMPORTS*****/
@import url('https://fonts.googleapis.com/css2?family=Fira+Mono:wght@400;500;700&family=Fira+Sans:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,100;1,200;1,300;1,400;1,500;1,600;1,700;1,800;1,900&display=swap');
/*****ROOT (COLOR AND FONT KEY)*****/ :root{
    /***main body (including CKEditor), modal(options menu), and some code colors (see last section for more code colors)***/
    --text-gray: lightgray;     --devils-gray-lol: #666;
    --background-gray: #111;     --supa-dark: black;     --midish-gray: #444;
    --bold-sun: #fcfbb3;     --bright-sun: #cccb99;     --dim-sun: #969573;
    --darkened-sun: #ccca6c;     --earth-sun: #333225;
    --light-turquoise: #6df9f7;     --sea-foam: #6df9b1;
    --italic-orange: #f4db92 /*#f4ba92*/;
    --border-orange: #cc862c /*#cc6c2c*/;     --sea-green: #04c963;
    --shallow-sea-blue: #54bcba;
    --header-font-family: 'Fira Sans', sans-serif;     --code-select-gray: #333;
    --table-header-gray: #222;     --soft-red: #ed363c;
    --code-comment: #a57489;     --code-tag: #06dd87;
    --code-string: #f7b2b2;     --code-number: #ea5474;
    --code-pseudo: #01ad6e;     --code-class: #269b4d;
    --code-keyword: var(--soft-red);     --code-meta: #777;
    --code-def: #5df7e8;     --code-var: #08a;     --code-builtin: #9368f7;
    --code-attribute: #CBEAD9; } /*****HTML (GENERAL STYLES)*****/
/******************************************************************
These are variables that already exist in the native stylesheet, just redefined here. This could have been put in ':root' or 'body{}' but for the sake of organization, I kept them in 'html' where they have been similarly placed in the Light Theme.
******************************************************************/ html {
    --theme-style: dark;     /***fonts***/     /*general fonts*/
    --main-font-family: 'Fira Sans', sans-serif;     --main-font-size: 1.2rem;
    --tree-font-family: 'Fira Sans', sans-serif;     --tree-font-size: 1.3rem;
    --detail-font-family: 'Fira Sans', sans-serif;
    --detail-font-size: 1.3rem;     /*code fonts*/
    --monospace-font-family: 'Fira Mono', monospace;
    --monospace-font-size: 1.2rem;     /***colors***/     /*main notes window*/
    --main-background-color: var(--background-gray);
    --main-text-color: var(--text-gray);
    --main-border-color: var(--devils-gray-lol);
    /*changes the window icons(x, [], -) and some text fields*/
    --accented-background-color: var(--supa-dark);
    /*changes the edit icons on text notes and the alert messages*/
    --more-accented-background-color: var(--midish-gray);
    /*left, bottom left, and lower upper right icons*/
    --button-background-color: transparent;
    --button-disabled-background-color: var(--midish-gray);
    --button-border-color: var(--text-gray);
    --button-text-color: var(--text-gray);     --button-border-radius: 5px;
    /*changes button in label detail*/
    --primary-button-background-color: var(--midish-gray);
    --primary-button-text-color:  var(--text-gray);
    --primary-button-border-color:  var(--text-gray);
    /* "muted-text-color" affects several components, but most are individually styled in this doc, so this should only affect the drop shadow of protected notes titles. */
    --muted-text-color: var(--devils-gray-lol);
    /*notes title and text fields in options menu and find (ctrl+f) search*/
    --input-text-color: var(--bright-sun);     /*affects all form inputs*/
    --input-background-color: var(--backround-gray);
    /*changes the 'x' on the note tabs and the right+click and trilium (icon) menus*/
    --hover-item-text-color: var(--text-gray);
    /*changes side and right+click menus and note tabs*/
    --hover-item-background-color: var(--supa-dark);     /*tree*/
    --active-item-text-color: var(--supa-dark);
    --active-item-background-color: var(--bright-sun);
    --left-pane-background-color: var(--supa-dark);
    --left-pane-text-color: var(--text-gray);     /*right+click menus*/
    --menu-text-color: var(--text-gray);
    --menu-background-color: var(--background-gray);     /*the options menu*/
    --modal-background-color: var(--background-gray);
    --modal-backdrop-color: var(--text-gray);     /*left and bottom left menus*/
    --launcher-pane-background-color: var(--background-gray);
    --launcher-pane-text-color: var(--dim-sun);     /*tabs*/
    --active-tab-background-color: var(--bold-sun);
    --active-tab-text-color: var(--background-gray);
    --active-tab-hover-background-color: var(--text-gray);
    --inactive-tab-background-color: var(--midish-gray);
    --inactive-tab-text-color: var(--text-gray);
    --inactive-tab-hover-background-color: var(--earth-sun);     /*general*/
    --scrollbar-border-color: var(--dim-sun);
    --tooltip-background-color: var(--background-gray);
    --link-color: var(--light-turquoise);     --mermaid-theme: dark; }
*:focus-visible {     outline: var(--bold-sun) auto 1px; }
/*****Image Caption*****/ .ck-content .image>figcaption {     font-size: 1rem; }
.ck-content figure.image>figcaption code {     font-size: .95rem; }
/*****Scrollbar*****/ ::-webkit-scrollbar-thumb{
    background-color: transparent !important; } ::-webkit-scrollbar-thumb:hover{
    border-color: var(--bright-sun) !important; } /*****TABS*****/
.tab-row-widget .note-tab .note-tab-wrapper {     height: 46px !important;
    font-size: var(--detail-font-size);
    font-family: var(--header-font-family); }
.tab-row-widget .note-tab .note-tab-title {     font-size: 1.5rem; }
.tab-row-widget .note-tab .note-tab-close {     font-size: 1.5rem;
    margin-bottom: 10px; } .note-tab div.note-tab-close.bx.bx-x:hover {
    background: transparent !important;     color: var(--bold-sun) !important; }
.note-tab[active] div.note-tab-close.bx.bx-x:hover {
    background: transparent !important;     color: var(--soft-red) !important; }
/*fixes the issue of not being able to access widgets in the top bar*/
.tab-row-filler {     -webkit-app-region: none !important; } /*****TOC*****/
/***Only applies if 'Show Position in TOC' widget is in use***/
.toc-widget span.toc li[style] {     color: var(--bold-sun) !important; }
.toc-widget span.toc li:not([style*="color:"]), .toc-widget span.toc li:not([style*="color:"]) * {
    color: inherit !important; }
.toc-widget .toc li, .highlights-list > ol > li {     text-align: left; }
.toc kbd {     background: transparent;     text-decoration: underline;
    color: inherit; } /*****Included Notes*****/ .include-note {
    margin-bottom: 1.1rem !important; } /*****HEADERS*****/
/*h1 is not defined, because it's not currently an option for headers in the main body*/
.ck-content h2 {     color: var(--darkened-sun);     font-weight: 800;
    font-family: var(--header-font-family);     font-size: 2rem; }
.ck-content h2 code, .ck-content h2 code b, .ck-content h2 code strong, .ck-content h2 code i, .ck-content h2 code em, .ck-content h2 kbd, .ck-content h2 kbd i, .ck-content h2 kbd b, .ck-content h2 kbd strong {
    font-size: 1.74rem;     background: transparent; }
.ck-content h2 kbd, .ck-content h2 kbd i, .ck-content h2 kbd b, .ck-content h2 kbd strong {
 text-decoration: underline; } .ck-content h3 {     color: var(--bright-sun);
    font-weight: 700;     font-family: var(--header-font-family);
    font-size: 1.9rem; }
.ck-content h3 code, .ck-content h3 code b, .ck-content h3 code strong, .ck-content h3 code i, .ck-content h3 code em, .ck-content h3 kbd, .ck-content h3 kbd i, .ck-content h3 kbd b, .ck-content h3 kbd strong {
    font-size: 1.6rem;     background: transparent; }
.ck-content h3 kbd, .ck-content h3 kbd i, .ck-content h3 kbd b, .ck-content h3 kbd strong {
 text-decoration: underline; } .ck-content h4 {     color: #6cccca;
    font-weight: 600;     font-family: var(--header-font-family);
    font-size: 1.78rem; }
.ck-content h4 code, .ck-content h4 code b, .ck-content h4 code strong, .ck-content h4 code i, .ck-content h4 code em, .ck-content h4 kbd, .ck-content h4 kbd i, .ck-content h4 kbd b, .ck-content h4 kbd strong {
    font-size: 1.3rem;     background: transparent; }
.ck-content h4 kbd, .ck-content h4 kbd i, .ck-content h4 kbd b, .ck-content h4 kbd strong {
 text-decoration: underline; } .ck-content h5 {     color: #99cccb;
    font-weight: 600;     font-family: var(--header-font-family);
    font-size: 1.65rem; }
.ck-content h5 code, .ck-content h5 code b, .ck-content h5 code strong, .ck-content h5 code i, .ck-content h5 code em, .ck-content h5 kbd, .ck-content h5 kbd i, .ck-content h5 kbd b, .ck-content h5 kbd strong {
    font-size: 1.2rem;     background: transparent; }
.ck-content h5 kbd, .ck-content h5 kbd i, .ck-content h5 kbd b, .ck-content h5 kbd strong {
 text-decoration: underline; } .ck-content h6 {     color: #99ccb1;
    font-weight: 600;     font-family: var(--header-font-family);
    font-size: 1.53rem; }
.ck-content h6 code, .ck-content h6 code b, .ck-content h6 code strong, .ck-content h6 code i, .ck-content h6 code em, .ck-content h6 kbd, .ck-content h6 kbd i, .ck-content h6 kbd b, .ck-content h6 kbd strong  {
    font-size: 1.1rem;     background: transparent; }
.ck-content h6 kbd, .ck-content h6 kbd i, .ck-content h6 kbd b, .ck-content h6 kbd strong {
 text-decoration: underline; } /*****TABLE*****/ .ck-content .table>figcaption {
    background-color: var(--table-header-gray);     color: var(--darkened-sun);
    font-size: 1.3rem;     font-weight: 600;
    font-family: var(--header-font-family); }
.ck-content .table table, .ck-content .table table td, .ck-content .table table th {
    border: none; } .ck-content .table table th {
    font-weight: 600 !important;     font-size: 1.15rem; } tr:nth-child(odd) {
    background-color: var(--code-select-gray); }
.ck-content .table table tbody tr:nth-child(odd) th {
    background-color: var(--table-header-gray) !important; }
.ck-content .table table {     width: 100%;     max-height: 90vh;
    overflow: auto; } .ck-content .table table thead th { position: sticky;
position: -webkit-sticky; top: 0; z-index: 1; }
.ck-content .table table tbody th { position: relative; }
.ck-content .table table thead th:first-child { position: sticky;
position: -webkit-sticky; left: 0; z-index: 2; }
.ck-content .table table tbody th { position: sticky; left: 0; z-index: 1; }
/*****TEXT DECORATION*****/ body strong, body b {   color:var(--bold-sun);
  font-weight: 700; } body i, body em {     color: var(--italic-orange); }
body u {     text-decoration-style: dashed; } body s, body del {
    text-decoration-style: double; } /*****LISTS*****/ li label {
    display: inline;     line-height: 2rem; }
.ck-content .todo-list .todo-list__label>input[checked]:before, .ck-editor__editable.ck-content .todo-list .todo-list__label>span[contenteditable=false]>input[checked]:before {
    background: var(--sea-green);     border-color: var(--sea-foam) !important;
}
.ck-content .todo-list .todo-list__label>input[checked]:after, .ck-editor__editable.ck-content .todo-list .todo-list__label>span[contenteditable=false]>input[checked]:after {
    border-color: var(--background-gray); }
.ck-content .todo-list .todo-list__label > input:not([checked]):before, .ck-editor__editable.ck-content .todo-list .todo-list__label>span[contenteditable=false]>input:not([checked]):before {
    border: 1px solid var(--soft-red) !important;
    background: var(--background-gray); } /*****CARDS*****/ /***blockquotes***/
body blockquote{     color: var(--italic-orange); } .ck-content blockquote {
    overflow: hidden;     padding-right: 0;     padding-left: 0.5em;
    margin: 1.5rem 10rem;     font-style: italic;     font-weight: 300;
    font-size: 1.65rem;     border-left: 5px solid var(--border-orange); }
.ck-content blockquote p {     margin-bottom: 0;     padding-bottom: .3em; }
.ck-content blockquote b {     font-weight: 500; }
.ck-content blockquote code, .ck-content blockquote kbd, .ck-content blockquote code strong, .ck-content blockquote kbd strong {
 font-size: 1.25rem; }
.ck-content blockquote code strong, .ck-content blockquote kbd strong {
    font-weight: 700; }
.ck-content blockquote i, .ck-content blockquote i > b, .ck-content blockquote i > strong, .ck-content blockquote em, .ck-content blockquote em > b, .ck-content blockquote em > strong {
 font-style: normal; } /***asides***/ .ck-content .admonition.note {
    --accent-color: var(--code-attribute) !important;     --rgb: 203, 234, 217;
} .ck-content .admonition.tip {     --accent-color: var(--code-var) !important;
    --rgb: 0, 136, 170; } .ck-content .admonition.important {
    --accent-color: var(--code-def) !important;     --rgb: 93, 247, 232; }
.ck-content .admonition.caution {
    --accent-color: var(--soft-red) !important;     --rgb: 237, 54, 60; }
.ck-content .admonition.warning {
    --accent-color: var(--code-string) !important;     --rgb: 247, 178, 178; }
.ck-content aside.admonition {     /*--accent-color: var(--card-border-color);*/
    --card-background-color: rgba(var(--rgb), .15);     border: none;
    border-left: 5px solid var(--accent-color);
    box-shadow: var(--card-box-shadow);
    background: var(--card-background-color);     border-radius: 0;
    padding: 0;     margin: 1.5rem 5rem;     position: relative;
    padding-left: 2em;     overflow: hidden;     font-weight: 300;
    font-size: 1.35rem; }    .ck-content aside.admonition::before {
    color: var(--accent-color);     font-family: boxicons !important;
    position: absolute;     top: 0;     left: .5em; } /***footnotes***/
/*Inline*/ span.footnote-reference > sup > a {     font-weight: 100;
    font-size: .9em; } /*Block*/ div.footnote-section.ck-widget {
    border: none;     border-top: 1px solid var(--devils-gray-lol);
    border-radius: 0;     counter-reset: footnote-counter;     margin: 2.5rem 0;
    padding: 10px 0;     opacity: 0.9;     font-size: 1.1rem; }
.ck-content span.footnote-back-link {     margin-right: 0;
    position: relative;     top: 0; } .ck-content li.footnote-item:before {
    font-variant-numeric: tabular-nums;
    content: counter(footnote-counter) ". ";     display: inline-block;
    min-width: 28px;     position: relative;     right: 0.2em;
    text-align: right;     overflow: hidden;     margin-left: -5px; }
/*****LINKS*****/ body a *, a.ck-widget span { color: var(--link-color); }
.ck-content a:hover {     text-decoration-style: double !important; }
.ck-content a[href^="#root"]:not(.ck-widget) {
    text-decoration: underline dotted; }
.ck-content a:not([href^="#"],[href^="https://"],[href^="http://"]) {
    color: var(--soft-red);     text-decoration: underline wavy 1px; }
/*****ICONS*****/ /*main note icon*/ .note-icon::before {
    color: var(--devils-gray-lol); } .note-icon:hover::before {
    color: var(--bold-sun);
    border-color: var(--bold-sun) !important; /*not working*/ }
.note-icon:focus::before, .bx-calendar:focus::before {
    color: var(--bold-sun); } .icon-list {     color: var(--shallow-sea-blue); }
/***note properties menu***/ .ribbon-tab-title-icon {
     color: var(--devils-gray-lol); } .ribbon-tab-title-icon:hover {
     color: var(--bold-sun); }
/***launcher, floating tree, icon action and title bar buttons***/
div.title-bar-buttons.component button, button.icon-action, .icon-action {
    color: var(--dim-sun) !important; }
#launcher-pane .launcher-button:hover, button.tree-floating-button:hover, .title-bar-buttons div:hover button, button.icon-action:hover, .icon-action:hover {
    color: var(--bold-sun) !important;     border: none !important; }
#launcher-pane button.launcher-button { padding: 0; } /***Calendar***/
div.dropdown-menu.dropdown-menu-right > div.calendar-dropdown-widget > div.calendar-body > a.calendar-date:hover, .calendar-dropdown-widget .calendar-btn:hover {
    color: var(--bold-sun) !important;
    background: var(--earth-sun) !important; }
a.calendar-date.calendar-date-exists {     color: var(--dim-sun); }
a.calendar-date.calendar-date-today {     background: var(--midish-gray); }
/***tree***/ /*note icon*/ .fancytree-custom-icon {     color: var(--dim-sun); }
.note-icon-widget button.note-icon {     border: none !important; }
span.fancytree-node.protected > span.fancytree-custom-icon {
    filter: drop-shadow(2px 2px 2px var(--shallow-sea-blue)); }
/*drop down icon*/ .fancytree-expander::before {
    color: var(--devils-gray-lol); } /*tree action buttons*/
button.tree-floating-button {     font-size: 1.5rem !important; }
/***Trilium icon***/ body .global-menu-button {
    background-image: url("/assets/vX/images/icon-grey.png"); }
/*****INPUT FIELDS*****/ /***password and options menu fields***/
.form-control {     color: var(--text-gray) !important; } .form-control:focus {
    color: var(--bright-sun) !important;     background-color: var(--supa-dark);
    border-color: var(--text-gray) !important;     outline: 0;
    box-shadow: 0 0 0 0.2rem rgb(252 251 179 / 50%) !important; }
.component.title-row{     margin-top: 10px;     margin-bottom: 10px; }
.note-title-widget input.note-title {
    font-family: var(--header-font-family);     font-size: 180% !important; }
.note-title:focus {     color: var(--text-gray) !important;
    background-color: var(--supa-dark) !important;
    border-color: var(--text-gray) !important;     outline: 0;
    box-shadow: 0 0 0 0.2rem rgb(252 251 179 / 50%) !important; }
/***selection and find/replace (button)***/ ::selection {
    color: black !important /*var(--supa-dark)*/;
    background: #fcfbb3 !important /*var(--bold-sun)*/; } span.ck-find-result {
    color: var(text-gray) !important;     background: var(--code-select-gray); }
span.ck-find-result_selected {     color: var(--supa-dark) !important;
    background: var(--bright-sun); } /***Empty note field***/
input.form-control.note-autocomplete.note-autocomplete-input.aa-input {
    height: auto; } /*****BUTTONS*****/ /***modal buttons***/
button.help-button {     color: var(--bright-sun);     font-size: 1.7rem; }
button.help-button:hover {     color: var(--dim-sun); } button.btn-close {
    filter: invert(1) } /***edit button***/ .bx-edit-alt {     height: 40px; }
/***primary and secondary buttons***/
button:focus :not(.close) :not(.help-button) :not(.ck-button-save) :not(.ck-button-cancel), .btn:focus {
    color: var(--text-gray) !important;
    background-color: var(--devils-gray-lol) !important;
    border-color: var(--text-gray) !important;     outline: 0;
    box-shadow: 0 0 0 0.2rem rgb(252 251 179 / 50%) !important; }
button:hover :not(.close) :not(.help-button) :not(.ck-button-save) :not(.ck-button-cancel), .btn:hover {
    background-color: var(--supa-dark) !important;     color: var(--bold-sun);
    border-color: var(--bold-sun); } /***table sub-menu***/
/*table field input label*/
.ck.ck-labeled-field-view>.ck.ck-labeled-field-view__input-wrapper>.ck.ck-label{
    background: var(--supa-dark);     color: var(--text-gray); }
/*table field and button inputs*/
.ck.ck-button:active, .ck.ck-button:focus, a.ck.ck-button:active, a.ck.ck-button:focus, .ck.ck-input-text:focus {
    border: 1px solid var(--text-gray) !important;
    box-shadow: 0 0 0 0.2rem rgb(252 251 179 / 50%) !important; }
.ck.ck-input-text[readonly]:focus {
    border: 1px solid var(--ck-color-input-disabled-border) !important;
    background: var(--ck-color-input-disabled-background) !important;
    color: var(--ck-color-input-disabled-text) !important; } /*color button*/
.ck.ck-input-color>.ck.ck-dropdown>.ck.ck-button.ck-input-color__button.ck-disabled, .ck.ck-input-color>.ck.ck-dropdown>.ck.ck-button.ck-input-color__button.ck-disabled>.ck.ck-input-color__button__preview, .ck.ck-input-color>.ck.ck-dropdown>.ck.ck-button.ck-input-color__button.ck-disabled>.ck.ck-input-color__button__preview>.ck.ck-input-color__button__preview__no-color-indicator {
    border: 1px solid var(--ck-color-input-disabled-border) !important; }
/*image caption field*/
.ck .ck-editor__nested-editable.ck-editor__nested-editable_focused, .ck .ck-editor__nested-editable:focus {
    background-color: var(--ck-color-widget-editable-focus-background);
    border: none /*var(--ck-focus-ring)*/;
    box-shadow: var(--ck-inner-shadow),0 0;     outline: none; }
/*backend logs*/ textarea.backend-log-textarea {
    color: var(--shallow-sea-blue) !important; } /*****NOTE MAP*****/
.note-detail-relation-map path, .note-detail-relation-map .jtk-endpoint{
    fill: var(--shallow-sea-blue) !important; } svg.jtk-connector path {
    stroke: var(--shallow-sea-blue);     fill: none !important; }
.note-detail-relation-map .note-box {     padding: 12px 30px 12px 12px;
    position: absolute !important;
    background-color: var(--accented-background-color);
    color: var(--main-text-color);     z-index: 4;     border: 1px solid #666;
    box-shadow: 2px 2px 19px #999;     border-radius: 8px;     opacity: 0.8;
    font-size: 1rem;     width: auto;     height: auto;     max-width: 240px;
    min-width: 150px;     max-height: 200px;     overflow: hidden; }
/*****FLOATING BUTTONS*****/ /***Backlinks Popup***/
.floating-buttons-children {     flex-direction: column-reverse !important; }
.backlinks-ticker {     padding: 6px 3px !important;
    writing-mode: vertical-lr;     margin-bottom: 15px; } div.backlinks-items {
    z-index: 10;     position: absolute;     top: 50px;     right: 10px;
    width: 400px;     border-radius: 10px;
    background-color: var(--supa-dark);     color: var(--text-gray);
    padding: 20px;     overflow-y: auto;
    box-shadow: 2px 2px 5px  var(--text-gray); } div.backlinks-items div:hover {
    background-color: var(--earth-sun); } .backlink-excerpt .backlink-link {
     background-color: var(--midish-gray) !important; }
.backlinks-ticker:hover {     background-color: var(--earth-sun); }
/***Relation Map and Canvas Buttons***/ .relation-map-buttons {
    display: flex;     gap: 10px;     flex-direction: column; }
.relation-map-buttons > .btn-group {     position: relative;
    display: -ms-inline-flexbox;     display: inline-flex;
    flex-direction: column;     vertical-align: middle; }
.relation-map-buttons > button, .relation-map-buttons > .btn-group button {
    border: none !important; }
