    const todayTasks = [];     const inboxTasks = [];
    const futureTasks = [];     const dkTasks = [];     const txTasks = [];
    // 按日期归组（受 today/future 开关控制）     const pushByDate = (item) => {
        if (item.date && item.date < today) {
            if (f.today) overdue.push(item);
        } else if (item.date && item.date === today) {
            if (f.today) todayTasks.push(item);
