        detach: "Detach from parent",         uninstall: "Uninstall"     }
    return {         addonId,         code,
        title: ISSUE_TITLES[code] || code,         target,         detail,
        fixes: fixes.filter(Boolean).map(fix => ({             ...fix,
            label: `${FIX_LABELS[fix.kind]}${fix.self ? " & reload" : ""}`
