    if (!res.ok) {         let detail = ""         try {
            const body = await res.json()
            detail = body.message || body.error || ""         } catch (e) {
            // Fall through to the status-only message.         }
        if (res.status === 400 || res.status === 401 || res.status === 403) {
            throw new Error(
